            if s.startswith("...", i):
                toks.append(Token("DOTS", "...", i))
                i+=3
            else:
                toks.append(Token("DOTS", "..", i))
                i+=2
            continue
        # single char
        single_map={
            "+":"PLUS","-":"MINUS","*":"STAR","/":"SLASH",
            "(": "LPAREN",")":"RPAREN","{":"LBRACE","}":"RBRACE",
            "[":"LBRACK","]":"RBRACK",";":"SEMI",",":"COMMA",
            ":":"COLON",".":"DOT","=":"EQ","<":"LT",">":"GT",
            "#":"HASH","$":"DOLLAR","|":"PIPE","!":"BANG","?":"QMARK",
            "_":"UNDERSCORE",
        }
        if c in single_map:
            toks.append(Token(single_map[c], c, i))
            i+=1
            continue
        if c=="<":
            toks.append(Token("LT", c, i))
            i+=1
            continue
        # unknown char like `#`? Actually # is valid in markup but not in code (error). We'll keep as HASH and later error.
        raise EvalError(f"unexpected character: {c}")
    toks.append(Token("EOF", None, n))
    return toks

